    public sealed class Sprint0029SystemsTests
    {
        GameSession session;string path;WarehouseMission mission;bool background;float volume;UnityEngine.Random.State random;
        [UnitySetUp]public IEnumerator Setup()
        {
            Assert.IsNull(GameSession.Instance);background=Application.runInBackground;Application.runInBackground=true;volume=AudioListener.volume;AudioListener.volume=0;random=UnityEngine.Random.state;UnityEngine.Random.InitState(2902);path=Path.Combine(Path.GetTempPath(),"Akumu29-"+Guid.NewGuid().ToString("N")+".json");session=new GameObject("Sprint29Session").AddComponent<GameSession>();session.Initialize(AssetDatabase.LoadAssetAtPath<GameCatalog>("Assets/Data/Progression/DemoCatalog.asset"),path);session.Data.owned.Add("carbine");session.Data.primary="carbine";session.Data.Ammo("carbine").magazine=24;session.Data.Ammo("carbine").reserve=108;session.Navigate(FlowScreen.Levels);session.SelectLevel("warehouse");session.PrepareMission();yield return Load("Warehouse_Demo");Quiet();
        }
        IEnumerator Load(string name){yield return EditorSceneManager.LoadSceneAsyncInPlayMode("Assets/Scenes/"+name+".unity",new LoadSceneParameters(LoadSceneMode.Single));yield return null;yield return null;mission=Object.FindAnyObjectByType<WarehouseMission>();}
        void Quiet(){mission.Player.GetComponent<Health>().ProtectFor(120);foreach(var p in mission.Encounters.SelectMany(e=>e.Points)){p.Spawned.GetComponent<EnemyCombat>().enabled=false;p.Spawned.enabled=false;p.Spawned.GetComponent<InsaneDreams.Prototype.PlayerMotor2D>().SetMoveInput(0);}}
        [UnityTearDown]public IEnumerator Cleanup(){Time.timeScale=1;yield return Load("Warehouse_Testbed");if(session!=null)Object.Destroy(session.gameObject);yield return null;foreach(var suffix in new[]{"",".bak",".tmp"})if(File.Exists(path+suffix))File.Delete(path+suffix);Application.runInBackground=background;AudioListener.volume=volume;UnityEngine.Random.state=random;}
        VisualElement Root=>Object.FindAnyObjectByType<UIDocument>().rootVisualElement;
        static void Click(Button b){Assert.NotNull(b);Assert.IsTrue(b.enabledInHierarchy,b.text);using(var e=NavigationSubmitEvent.GetPooled()){e.target=b;b.SendEvent(e);}}
        Button Named(string text)=>Root.Query<Button>().ToList().Single(b=>b.text==text);
        IEnumerator Capture(string name){int frame=Time.frameCount;yield return new WaitForSeconds(.2f);Assert.Greater(Time.frameCount,frame+1,"Capture an advancing game");yield return new WaitForEndOfFrame();ScreenCapture.CaptureScreenshot("TestResults/Sprint0029/"+name+".png");yield return new WaitForEndOfFrame();yield return null;}
        [UnityTest]public IEnumerator PurchasedChargesAutoReviveOnceProtectAllDamageForTwoSecondsAndNeverCheckpointRefill()
        {
            session.Data.faintanyl=2;mission.GetComponent<CampaignMissionBridge>().ApplyEquipment();var hp=mission.Player.GetComponent<Health>();var revive=mission.Player.GetComponent<PlayerRevive>();float revived=-1;revive.Revived+=()=>revived=Time.time;int plays=mission.Player.GetComponent<PlayerSyringeVisual>().PlayCount;
            for(int i=0;i<2;i++)
            {
                hp.ProtectFor(0);Assert.IsTrue(hp.ApplyDamage(new DamageInfo(10000,CombatTeam.Enemy)));Assert.IsTrue(hp.IsDefeated);Assert.IsFalse(mission.AttemptFailed);Assert.AreEqual(1-i,revive.Injections,"Charge commits on death, before delayed animation");Assert.AreEqual(0,new ProgressStore(path).Load(()=>new GameProgress()).faintanyl,"Deployed injections remain reserved on disk");
                float end=Time.time+1;while(hp.IsDefeated&&Time.time<end)yield return null;Assert.IsFalse(hp.IsDefeated);Assert.That(revive.ProtectionRemaining,Is.InRange(1.95f,2));Assert.IsFalse(revive.TryRevive());Assert.AreEqual(DisplayStyle.None,Root.Q("reviveOverlay").resolvedStyle.display);Assert.AreEqual(plays+i+1,mission.Player.GetComponent<PlayerSyringeVisual>().PlayCount);yield return new WaitForEndOfFrame();Assert.IsTrue(Root.Q("revivePip"+(1-i)).ClassListContains("is-empty"));
                while(Time.time<revived+1.9f)yield return null;foreach(DamageKind kind in Enum.GetValues(typeof(DamageKind)))Assert.IsFalse(hp.ApplyDamage(new DamageInfo(1,CombatTeam.Enemy,null,null,false,kind)));while(Time.time<revived+2.02f)yield return null;Assert.IsTrue(hp.ApplyDamage(new DamageInfo(1,CombatTeam.Enemy)));Assert.AreEqual(99,hp.Current);
            }
            mission.Player.GetComponent<InsaneDreams.Checkpoints.PlayerRecovery>().Respawn();Assert.AreEqual(0,revive.Injections);hp.ProtectFor(0);hp.ApplyDamage(new DamageInfo(10000,CombatTeam.Enemy));yield return new WaitForSeconds(.5f);Assert.IsTrue(hp.IsDefeated);Assert.IsTrue(mission.AttemptFailed);Assert.AreEqual(0,session.Data.faintanyl);
        }
        [UnityTest]public IEnumerator HeavyGearCapsCarryKeepsStoredOverflowAndPreservesMovementAndPhysicalDeathHelmet()
        {
            var player=mission.Player;var motor=player.GetComponent<InsaneDreams.Prototype.PlayerMotor2D>();float speed=motor.MoveSpeed,jump=motor.JumpSpeed,gravity=player.GetComponent<Rigidbody2D>().gravityScale;var bridge=mission.GetComponent<CampaignMissionBridge>();var data=session.Data;data.bodyArmorTier=2;data.armor=90;data.helmetTier=2;data.helmet=35;data.grenades=new[]{5,5,5};data.Ammo(data.primary).magazine=2;data.Ammo(data.primary).reserve=432;bridge.ApplyEquipment();var loadout=player.GetComponent<PlayerLoadout>();var gun=loadout.Get(EquipmentSlot.Firearm1);var grenades=player.GetComponent<PlayerThrowables>();Assert.AreEqual(378,loadout.MaximumReserveAmmo);Assert.AreEqual(session.Catalog.ReserveCapacity(data,session.Catalog.Find(data.primary)),gun.ReserveAmmo);Assert.AreEqual(4,grenades.MaximumCapacity);Assert.AreEqual(4,grenades.Count(ThrowableKind.Fragmentation));Assert.AreEqual(1.274f,gun.ReloadMultiplier,.001f);Assert.AreEqual(speed,motor.MoveSpeed);Assert.AreEqual(jump,motor.JumpSpeed);Assert.AreEqual(gravity,player.GetComponent<Rigidbody2D>().gravityScale);Assert.IsTrue(player.GetComponent<ArmorVisual>().helmetOverlay.enabled);
            player.GetComponent<PlayerCombat>().Reload();Assert.AreEqual(gun.Definition.ReloadDuration*1.274f,gun.Cycle.ReloadEndsAt-gun.Cycle.ReloadStartedAt,.001f);yield return new WaitForSeconds(gun.Definition.ReloadDuration*1.274f+.1f);Assert.AreEqual(24,gun.MagazineAmmo);Assert.AreEqual(session.Catalog.ReserveCapacity(data,session.Catalog.Find(data.primary))-22,gun.ReserveAmmo);
            loadout.Select(EquipmentSlot.Melee);player.SetTouchAim(new Vector2(1,.4f));yield return new WaitForSeconds(.15f);Assert.IsTrue(grenades.IsAiming);Assert.AreEqual(4,grenades.Count(ThrowableKind.Fragmentation));player.SetTouchAim(Vector2.zero);yield return new WaitForSeconds(.12f);Assert.AreEqual(1,grenades.Throws);Assert.AreEqual(3,grenades.Count(ThrowableKind.Fragmentation));bridge.SendMessage("OnApplicationPause",true);var stored=new ProgressStore(path).Load(()=>new GameProgress());Assert.AreEqual(410,stored.Ammo(data.primary).reserve,"Paused inventory and unpacked rounds preserved");Assert.AreEqual(4,stored.grenades[0],"Paused carried stock and one unpacked frag preserved");bridge.SendMessage("OnApplicationPause",false);Assert.AreEqual(1,new ProgressStore(path).Load(()=>new GameProgress()).grenades[0],"Resume reserves carried stock again before simulation");Assert.AreEqual("3/4",Root.Q<Label>("ammoValue").text);
            var crate=Object.FindObjectsByType<SupplyCrate2D>().OrderBy(c=>c.transform.position.x).First();var rb=player.GetComponent<Rigidbody2D>();rb.position=new Vector2(crate.transform.position.x-.8f,.72f);player.transform.position=rb.position;rb.linearVelocity=Vector2.zero;Physics2D.SyncTransforms();yield return new WaitForSeconds(.15f);Assert.IsTrue(crate.TrySupply(player.GetComponent<PlayerSupplies>()));Assert.AreEqual(4,grenades.Count(ThrowableKind.Fragmentation));Assert.AreEqual(session.Catalog.ReserveCapacity(data,session.Catalog.Find(data.primary)),gun.ReserveAmmo);Assert.AreEqual(1,crate.GrenadesLeft(ThrowableKind.Fragmentation));Assert.AreEqual(2,crate.GrenadesLeft(ThrowableKind.Flashbang));bridge.SendMessage("OnApplicationPause",true);Assert.AreEqual(432,session.Data.Ammo(data.primary).reserve);Assert.AreEqual(5,session.Data.grenades[0]);
            data.bodyArmorTier=1;data.armor=60;data.helmetTier=1;data.helmet=20;bridge.ApplyEquipment();Assert.AreEqual(session.Catalog.ReserveCapacity(data,session.Catalog.Find(data.primary)),loadout.Get(EquipmentSlot.Firearm1).ReserveAmmo);Assert.AreEqual(5,grenades.Count(ThrowableKind.Fragmentation));Assert.AreEqual(5,grenades.MaximumCapacity);player.GetComponent<Health>().ProtectFor(0);player.GetComponent<Health>().ApplyDamage(new DamageInfo(10000,CombatTeam.Enemy,null,null,false,DamageKind.Melee));Assert.NotNull(player.GetComponent<PlayerDeathRagdoll>().Corpse.Bodies[1].transform.Find("ArmorHelmet"));
        }
        [UnityTest]public IEnumerator FullMenuMedicalAmmoMissionResultsFlowKeepsFourCategoriesAndAtomicPurchases()
        {
            mission.GetComponent<CampaignMissionBridge>().ReturnToLevels();while(SceneManager.GetActiveScene().name!="MainMenu")yield return null;yield return null;yield return null;session.Data.balance=10000;session.Data.tape=0;session.Data.faintanyl=0;Click(Named("MAIN MENU"));yield return null;Click(Named("PLAY"));yield return null;Click(Named("PREPARE EQUIPMENT"));yield return null;Assert.AreEqual(4,Root.Q("shopCategories").childCount);Click(Named("Medical"));yield return null;Assert.AreEqual(2,Root.Q("medicalShop").childCount);Assert.IsTrue(Root.Query<Label>().ToList().Any(l=>l.text=="There is nothing duct tape can't fix."));Assert.IsTrue(Root.Query<Label>().ToList().Any(l=>l.text=="relax its not addictive, just habit forming"));
            Click(Root.Q<Button>("procureDuctTape"));yield return new WaitForSecondsRealtime(.3f);Click(Root.Q<Button>("procureFaintanyl"));yield return new WaitForSecondsRealtime(.3f);Click(Root.Q<Button>("procureFaintanyl"));Assert.AreEqual(50,session.Data.tape);Assert.AreEqual(2,session.Data.faintanyl);Assert.AreEqual(10000-session.Catalog.Find("tape").price-2*session.Catalog.Find("faintanyl").price,session.Data.balance);Assert.IsFalse(Root.Q<Button>("procureFaintanyl").enabledInHierarchy);Click(Named("BACK TO LEVELS"));yield return null;Click(Named("PREPARE EQUIPMENT"));yield return null;Click(Named("Ammunition"));yield return null;Assert.IsNull(Root.Q("medicalShop"));var frag=session.Catalog.Find("frag-grenade");Click(Root.Query<Button>().ToList().Single(b=>b.text==frag.title+"  $"+frag.price));yield return new WaitForSecondsRealtime(.3f);Click(Named("BUY"));Assert.AreEqual(1,session.Data.grenades[0]);int wallet=session.Data.balance;Click(Named("START MISSION — PURCHASE OPTIONAL"));
            float deadline=Time.realtimeSinceStartup+20;while(SceneManager.GetActiveScene().name!="Warehouse_Demo"&&Time.realtimeSinceStartup<deadline)yield return null;yield return null;yield return null;mission=Object.FindAnyObjectByType<WarehouseMission>();Assert.NotNull(mission);Quiet();Assert.AreEqual(2,mission.Player.GetComponent<PlayerRevive>().Injections);Assert.NotNull(Root.Q<Image>("revivePip0").sprite);Assert.NotNull(Root.Q<Image>("revivePip1").sprite);Assert.AreEqual(1,mission.Player.GetComponent<PlayerThrowables>().Count(ThrowableKind.Fragmentation));var gun=mission.Player.GetComponent<PlayerLoadout>().SelectedWeapon;Assert.AreEqual(gun.MagazineAmmo+"/"+gun.Definition.MagazineCapacity,Root.Q<Label>("ammoValue").text);
            foreach(var p in mission.Encounters.SelectMany(e=>e.Points))p.Spawned.GetComponent<Health>().ApplyDamage(new DamageInfo(10000,CombatTeam.Player,mission.Player.gameObject));var exit=Object.FindObjectsByType<MissionTrigger>().Single(t=>t.Zone==MissionZone.Exit);var body=mission.Player.GetComponent<Rigidbody2D>();body.position=new Vector2(exit.transform.position.x,.72f);mission.Player.transform.position=body.position;Physics2D.SyncTransforms();mission.EnterZone(MissionZone.Exit,exit.GetComponent<Collider2D>());yield return new WaitForSeconds(.15f);Assert.AreEqual(MissionStage.Complete,mission.Stage);int earnings=mission.Earnings;Click(Named("LEVEL SELECTION"));while(SceneManager.GetActiveScene().name!="MainMenu")yield return null;yield return null;Assert.AreEqual(FlowScreen.Levels,session.Screen);Assert.IsTrue(session.Data.completed.Contains("warehouse"));Assert.AreEqual(wallet+session.Catalog.Payout(earnings,true),session.Data.balance);var stored=new ProgressStore(path).Load(()=>new GameProgress());Assert.AreEqual(2,stored.faintanyl);Assert.AreEqual(50,stored.tape);Assert.AreEqual(1,stored.grenades[0]);
        }
        [UnityTest]public IEnumerator ChunkyTypographyAmmoSwitchingAndMedicalIconsPreserveTouchGeometry()
        {
            session.Data.faintanyl=2;session.Data.bodyArmorTier=2;session.Data.armor=90;session.Data.helmetTier=2;session.Data.helmet=35;mission.GetComponent<CampaignMissionBridge>().ApplyEquipment();yield return new WaitForSeconds(.25f);var font=AssetDatabase.LoadAssetAtPath<Font>("Assets/Art/Interface0029/AkumuBlock.ttf");Assert.NotNull(font);var def=Root.Q<Label>("ammoValue").resolvedStyle.unityFontDefinition;Assert.IsTrue(def.font==font||def.fontAsset!=null&&def.fontAsset.faceInfo.familyName=="AKUMU Block","HUD must use the project block font");Assert.GreaterOrEqual(Root.Q("moveStick").worldBound.width,140);Assert.GreaterOrEqual(Root.Q("aimStick").worldBound.width,140);Assert.AreEqual(52,Root.Q("pauseVisual").worldBound.width,1);Assert.AreEqual(40,Root.Q("pauseVisual").worldBound.height,1);Assert.GreaterOrEqual(Root.Q("campaignPause").worldBound.width,100);Assert.GreaterOrEqual(Root.Q("campaignPause").worldBound.height,52);Assert.AreEqual(Root.Q("safeArea").worldBound.center.x,Root.Q("campaignPause").worldBound.center.x,1);Assert.IsNull(Root.Q("fireSecondary"));Assert.NotNull(Root.Q<Image>("revivePip0").sprite);Assert.IsTrue(Root.Q<Label>("tapeValue").text.StartsWith("DUCT TAPE"));Assert.IsTrue(Root.Q<Label>("armorValue").text.Contains("HELMET"));
            var loadout=mission.Player.GetComponent<PlayerLoadout>();var gun=loadout.SelectedWeapon;gun.SetAmmunition(16,100);yield return new WaitForSeconds(.25f);Assert.AreEqual("16/"+gun.Definition.MagazineCapacity,Root.Q<Label>("ammoValue").text);int rounds=gun.MagazineAmmo;mission.Player.SetFireIntent(true);yield return new WaitForSeconds(.12f);mission.Player.SetFireIntent(false);yield return new WaitForSeconds(.25f);Assert.Less(gun.MagazineAmmo,rounds);Assert.AreEqual(gun.MagazineAmmo+"/"+gun.Definition.MagazineCapacity,Root.Q<Label>("ammoValue").text);Assert.IsTrue(Root.Q<Label>("reserveValue").text.Contains("100"));yield return Capture("HUD");
            var side=session.Catalog.offers.First(o=>o.category==ShopCategory.Weapons&&o.weapon.WeaponCategory==WeaponCategory.Firearm&&o.weapon.MagazineCapacity==27);var pistol=new RuntimeWeapon(side.weapon,70);pistol.SetAmmunition(16,70);loadout.Equip(EquipmentSlot.Firearm2,pistol);loadout.Select(EquipmentSlot.Firearm2);yield return new WaitForSeconds(.25f);Assert.AreEqual("16/27",Root.Q<Label>("ammoValue").text);yield return Capture("PistolHUD");
            Assert.LessOrEqual(Root.Q("reserveValue").worldBound.xMax,Root.Q("ammoValue").parent.worldBound.xMax+.5f,"Reserve must fit its panel");mission.GetComponent<CampaignMissionBridge>().ReturnToLevels();while(SceneManager.GetActiveScene().name!="MainMenu")yield return null;yield return null;yield return null;session.Data.tape=150;session.Data.faintanyl=1;Click(Named("MAIN MENU"));yield return null;yield return Capture("MainMenu");Click(Named("PLAY"));yield return null;Click(Named("PREPARE EQUIPMENT"));yield return null;Click(Named("Medical"));yield return null;yield return Capture("MedicalShop");Assert.LessOrEqual(Root.Q("procureFaintanyl").worldBound.yMax,Root.worldBound.yMax,"Both Medical purchase buttons visible in landscape");Click(Named("Body armor"));yield return null;yield return Capture("ArmorShop");
        }
    }
